theorem interMember_image_subset {U : CoverFamily X I} {V : CoverFamily X J}
    (R : Refinement U V) (σ : Finset I) :
    interMember U σ ⊆ interMember V (σ.image R.selector)

theorem nerveMap_comp {U : CoverFamily X I} {V : CoverFamily X J}
    {W : CoverFamily X K} (R : Refinement U V) (S : Refinement V W) :
    nerveMap (Refinement.comp R S) = VertexMap.comp (nerveMap R) (nerveMap S)

@[simp] theorem comp_selector {U : CoverFamily X I} {V : CoverFamily X J}
    {W : CoverFamily X K} (R : Refinement U V) (S : Refinement V W) :
    (comp R S).selector = fun i => S.selector (R.selector i)

theorem comp_assoc {U : CoverFamily X I} {V : CoverFamily X J} {W : CoverFamily X K}
    {Z : CoverFamily X L} (R : Refinement U V) (S : Refinement V W)
    (T : Refinement W Z) : comp (comp R S) T = comp R (comp S T)

theorem pullbackRefinement_id {Y : Type z} {U : CoverFamily Y I} {V : CoverFamily Y J}
    (R : Refinement U V) :
    (pullbackRefinement (fun y => y) R).selector = R.selector

theorem pullbackRefinement_comp {Y : Type z} {Z : Type s}
    (f : X → Y) (g : Y → Z) {U : CoverFamily Z I} {V : CoverFamily Z J}
    (R : Refinement U V) :
    (pullbackRefinement f (pullbackRefinement g R)).selector =
      (pullbackRefinement (g ∘ f) R).selector

theorem preimageSetInclusion_id (f : C(X, Y)) (A : Set Y) :
