    e.1.orderEmbOfFin e.2.2 = pairEmb a b hab

private theorem edge01_boundary :
    boundary cycleK ℚ 0 (Finsupp.single edge01 1) =
      Finsupp.single (vertexFace 1) 1 - Finsupp.single (vertexFace 0) 1

private theorem edge12_boundary :
    boundary cycleK ℚ 0 (Finsupp.single edge12 1) =
      Finsupp.single (vertexFace 2) 1 - Finsupp.single (vertexFace 1) 1

private theorem edge23_boundary :
    boundary cycleK ℚ 0 (Finsupp.single edge23 1) =
      Finsupp.single (vertexFace 3) 1 - Finsupp.single (vertexFace 2) 1

private theorem edge03_boundary :
    boundary cycleK ℚ 0 (Finsupp.single edge03 1) =
      Finsupp.single (vertexFace 3) 1 - Finsupp.single (vertexFace 0) 1

private theorem pendantRadius_eq_nearest {x : PendantCycle} (hx : x ≠ some (0 : Fin 4)) :
    radius (some (0 : Fin 4)) (insertionIndex (some (0 : Fin 4)) x - 1) =
      nearestDistance (greedyPrefix (some (0 : Fin 4)) (insertionIndex (some (0 : Fin 4)) x - 1)) x

private theorem coreRadius_ge_one {i : Fin 4} (hi : i ≠ 0) :
    1 ≤ radius (some (0 : Fin 4))
      (insertionIndex (some (0 : Fin 4)) (some i) - 1)

private theorem pendantRadius_le :
    radius (some (0 : Fin 4))
      (insertionIndex (some (0 : Fin 4)) (none : PendantCycle) - 1) ≤ 1 / 20

theorem relaxedDistance_left_le {η r : ℝ} {time : V → Option ℝ} {x q y : V}
    (hq : dist x q ≤ weight η (time x) r - weight η (time q) r) :
    relaxedDistance η time r q y ≤ relaxedDistance η time r x y

theorem isIso_closedActiveHomologyIncl (R : Type*) [Ring R] (seed : V) {η r : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (hr : 0 ≤ r) (n : ℕ) :
    IsIso (simplicialHomologyIncl R (closedActiveComplex_le_relaxedComplex seed η r) n)

theorem finiteWeight_of_between {η t r : ℝ}
    (h₁ : (1 - 2 * η) * t < r) (h₂ : r < t) :
    finiteWeight η t r = (r - (1 - 2 * η) * t) / 2

theorem sparseFilter_sublevel_eq (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (r : ℝ) :
    (sparseFilter seed η).sublevel r = sparseComplex seed η r

theorem sparseFilter_sublevelFiltration_eq (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) :
    (sparseFilter seed η).sublevelFiltration = sparseFiltration seed η

theorem sparseFilter_positiveOnEdges [LinearOrder V] (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) :
    PositiveOnEdges (sparseFilter seed η)

theorem isIso_closedActive_sparse (R : Type*) [Ring R] (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) {r : ℝ} (hr : 0 ≤ r) (n : ℕ) :
    IsIso (simplicialHomologyIncl R (closedActiveComplex_le_sparseComplex seed η hr) n)

theorem isIso_sparse_relaxed (R : Type*) [Ring R] (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) {r : ℝ} (hr : 0 ≤ r) (n : ℕ) :
    IsIso (simplicialHomologyIncl R (sparseComplex_le_relaxedComplex seed hη hη' r) n)

theorem sparseComplex_eq_activeUnion_deletionGrid (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (r : ℝ) :
    sparseComplex seed η r = activeUnion seed η (deletionGrid seed η r)

theorem sparseComplex_le_relaxedComplex (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (r : ℝ) :
    sparseComplex seed η r ≤ relaxedComplex η (deletionTime seed η) r

theorem closedActive_of_openActive_of_noDeletion (seed : V) {η r s : ℝ}
    (hgap : NoDeletionBetween seed η r s) {x : V}
    (hx : OpenActive (deletionTime seed η x) r) :
    ClosedActive (deletionTime seed η x) s

theorem deletionMap_fixes_later (seed : V) {η r s : ℝ}
    (hη : 0 ≤ η) (hr : 0 ≤ r) (hrs : r < s) {x : V}
    (hx : ClosedActive (deletionTime seed η x) s) : deletionMap seed η r hη hr x = x

theorem deletionMap_image_later (seed : V) {η r s : ℝ}
    (hη : 0 ≤ η) (hr : 0 ≤ r) (hrs : r < s) {σ : Finset V}
    (hσ : σ ∈ closedActiveComplex seed η s) :
    σ.image (deletionMap seed η r hη hr) = σ

theorem image_mem_later_of_noDeletion (seed : V) {η r s : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (hr : 0 ≤ r) (hrs : r ≤ s)
    (hgap : NoDeletionBetween seed η r s) {σ : Finset V}
    (hσ : σ ∈ closedActiveComplex seed η r) :
    σ.image (deletionMap seed η r hη.le hr) ∈ closedActiveComplex seed η s

theorem laterNeighbor_closedActive_at_time (seed : V) {η : ℝ}
    (hη : 0 < η) (hη' : η ≤ 1 / 3) (p : V) {q : V}
    (hq : q ∈ laterNeighbors seed η p) :
    ClosedActive (deletionTime seed η q)
      (radius seed (insertionIndex seed p - 1) / (η * (1 - 2 * η)))

theorem exists_assigned_vertex (seed : V) (η : ℝ) {σ : Finset V}
    (hσ : σ ∈ sparseCarrier seed η) :
    ∃ p ∈ σ, σ.erase p ⊆ laterNeighbors seed η p

private theorem dgm_eq_of_heq {K L : PreAbstractSimplicialComplex ℕ}
    (iK : Fintype (TotalFace K)) (iL : Fintype (TotalFace L))
    (hK : K = L) (f : FilterFunction K ℤ) (g : FilterFunction L ℤ)
    (hf : HEq f g) (p : ℕ) :
    @dgm ℕ _ (ZMod 2) _ ℤ _ K iK f p =
      @dgm ℕ _ (ZMod 2) _ ℤ _ L iL g p

private theorem single_degree_support (degree : Fin m → ℕ)
    (op : EarlierColumnOp m k) (hdegree : degree op.1.i = degree op.1.j)
    (r c : Fin m) (hrc : degree r ≠ degree c) : op.1.toMatrix r c = 0

private theorem qZero_height_decrease :
    pivotHeight (columnPivot (cancelColumn qSourceZero qTargetZero 0)) <
      pivotHeight (columnPivot qTargetZero)

private theorem qLower_height_decrease :
    pivotHeight (columnPivot (cancelColumn qSourceLower qTargetLower 1)) = 1 ∧
      pivotHeight (columnPivot qTargetLower) = 2

private theorem f2_transvection_height_decrease :
    pivotHeight (columnPivot (f2TransvectionMatrix.col 1)) = 0 ∧
      pivotHeight (columnPivot (f2Matrix.col 1)) = 1

private theorem zeroMixed_mixed_essential_counts :
    (essentialSurvivorFinset mixedDegree zeroMixed 0 3).card = 2 ∧
      (essentialSurvivorFinset mixedDegree zeroMixed 2 3).card = 1

private theorem interleaved_survives_before_death :
    aliveRepresentative interleavedDegree interleaved 0 2
      (Pi.single (0 : Fin 4) (1 : ℚ)) = Pi.single 0 1

private theorem interleaved_dies_at_death :
    aliveRepresentative interleavedDegree interleaved 0 3
      (Pi.single (0 : Fin 4) (1 : ℚ)) = 0

private theorem interleavedEssential_pairs :
    columnPivot (interleavedEssential.col (3 : Fin 5)) = some (0 : Fin 5) ∧
    columnPivot (interleavedEssential.col (4 : Fin 5)) = some (2 : Fin 5)

private theorem interleavedEssential_cycle_survives :
    aliveRepresentative interleavedEssentialDegree interleavedEssential 0 5
      (Pi.single (1 : Fin 5) (1 : ℚ)) = Pi.single 1 1

